// Holt alle Buchungen seitenweise ueber limit[start] und limit[reply].
// Nachweislich wirksame Schreibweise, Hoechstwert der Seitengroesse 2000.
// Personenbezogene Angaben werden nicht uebernommen, der Besitzer nur als
// nicht umkehrbarer Streuwert, den die Datenbank selbst bildet.

const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

const basis = 'https://app1.edoobox.com/v2/booking/list';
const seitengroesse = 500;
const hoechstzahl_seiten = 40;

const gesammelt = new Map();
let abrufe = 0;
let gemeldet_total = null;
let versatz = 0;

for (let seite = 0; seite < hoechstzahl_seiten; seite += 1) {
  const antwort = await this.helpers.httpRequest({
    method: 'GET',
    url: basis,
    headers,
    qs: { 'limit[start]': versatz, 'limit[reply]': seitengroesse },
    json: true,
    returnFullResponse: true,
    timeout: 120000,
  });
  abrufe += 1;

  if (antwort.statusCode !== 200) {
    throw new Error(`Seite ab ${versatz} lieferte Status ${antwort.statusCode}`);
  }

  const huelle = antwort.body?.limit ?? {};
  if (gemeldet_total === null) gemeldet_total = huelle.total ?? null;

  const roh = antwort.body?.data;
  const eintraege = roh && typeof roh === 'object' && !Array.isArray(roh) ? Object.entries(roh) : [];

  if (eintraege.length === 0) break;

  // Sicherung gegen einen nicht angenommenen Versatz: wiederholt sich die
  // erste Kennung, wird abgebrochen statt endlos dasselbe zu holen.
  const ersteKennung = eintraege[0][1]?.id ?? eintraege[0][0];
  if (versatz > 0 && gesammelt.has(ersteKennung) && huelle.start !== versatz) {
    throw new Error('Der Versatz wurde nicht angenommen, Abbruch zur Sicherheit.');
  }

  for (const [schluessel, satz] of eintraege) {
    const b = satz && typeof satz === 'object' ? satz : {};
    const kennung = b.id ?? schluessel;
    if (!kennung || !b.offer) continue;

    gesammelt.set(kennung, {
      id: String(kennung),
      offer: String(b.offer),
      time: b.time ?? null,
      status: b.canceled ? 'storniert' : b.waiting_list ? 'warteliste' : 'gebucht',
      owner: b.owner ? String(b.owner) : null,
      mustpay: b.mustpay === true,
      label: b.label ?? null,
    });
  }

  versatz += seitengroesse;
  if (gemeldet_total !== null && versatz >= gemeldet_total) break;
}

const saetze = [...gesammelt.values()];

return [
  {
    json: {
      schritt: 'S11',
      run_id: $('S11 Vollabgleich starten').first().json.run_id,
      gemeldet_total,
      eingesammelt: saetze.length,
      abrufe,
      vollstaendig: gemeldet_total !== null ? saetze.length >= gemeldet_total : null,
      datenJson: JSON.stringify(saetze),
    },
  },
];
